import itertools as it, math, pickle, os
import numpy as np

def make(m):
 k=m-5
 cells=[]; ids=[]
 for q in range(5):
  cs=[]
  for S in it.combinations(range(m),q):
   U=tuple(x for x in range(m) if x not in S); p=U[0]
   for a in it.product(range(3),repeat=q):
    if any(a.count(i)>2 for i in range(3)):continue
    for R in it.combinations(U[1:], k):
     cs.append((tuple(zip(S,a)),(p,)+R))
  cells.append(cs);ids.append({c:i for i,c in enumerate(cs)})
 mats=[]
 for q in range(1,5):
  cols=[]
  for sig,tau in cells[q]:
   d={}
   for j in range(q):
    sig2=sig[:j]+sig[j+1:];p=next(x for x in range(m) if x not in dict(sig2))
    if p in tau: terms=[(tau,1)]
    else:
     u=tuple(sorted((p,)+tau));ip=u.index(p)
     terms=[(u[:h]+u[h+1:],(-1)**(h-ip+1)) for h in range(len(u)) if h!=ip]
    for t,s in terms:
     row=ids[q-1][sig2,t];d[row]=d.get(row,0)+(-1)**j*s
   cols.append({x:y for x,y in d.items() if y})
  mats.append(cols)
 return [len(c) for c in cells],mats

def rank(cols,p):
 piv={}
 for co in cols:
  co={i:v%p for i,v in co.items() if v%p}
  while co:
   i=min(co)
   if i not in piv:
    iv=pow(int(co[i]),-1,p);piv[i]={j:v*iv%p for j,v in co.items()};break
   a=co[i]; other=piv[i]
   for j,v in other.items():
    t=(co.get(j,0)-a*v)%p
    if t:co[j]=t
    elif j in co:del co[j]
 return len(piv)
if __name__=='__main__':
 for m in [7,8,9]:
  fn=f'mats{m}.pkl'
  if os.path.exists(fn):dims,mats=pickle.load(open(fn,'rb'))
  else:
   dims,mats=make(m);pickle.dump((dims,mats),open(fn,'wb'))
  print('m',m,'dims',dims,flush=True)
  for p in [2,3,5,101]:
   ranks=[0]+[rank(mat,p) for mat in mats]+[0]
   print(p,[dims[q]-ranks[q]-ranks[q+1] for q in range(5)],flush=True)

